package com.cpf.starter.quartz;import java.util.Properties;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.Bean;import org.springframework.scheduling.quartz.SchedulerFactoryBean;
@AutoConfiguration @EnableConfigurationProperties(CpfQuartzProperties.class) @ConditionalOnProperty(prefix="cpf.scheduler.quartz",name="enabled",havingValue="true") public class CpfQuartzAutoConfiguration {@Bean SchedulerFactoryBean cpfQuartzSchedulerFactory(CpfQuartzProperties p){p.validate();Properties q=new Properties();q.setProperty("org.quartz.scheduler.instanceName",p.getInstanceName());q.setProperty("org.quartz.scheduler.instanceId","AUTO");q.setProperty("org.quartz.threadPool.threadCount",Integer.toString(p.getThreadCount()));q.setProperty("org.quartz.jobStore.isClustered",Boolean.toString(p.isClustered()));q.setProperty("org.quartz.jobStore.misfireThreshold",Long.toString(p.getMisfireThreshold()));SchedulerFactoryBean f=new SchedulerFactoryBean();f.setQuartzProperties(q);f.setWaitForJobsToCompleteOnShutdown(true);f.setOverwriteExistingJobs(false);return f;}}
